 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Cat Care FAQ</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f6f8fb;
         --surface: #ffffff;
         --surface-strong: #f0f5ff;
         --text: #132033;
         --muted: #5f6f86;
         --accent: #2854d8;
         --accent-strong: #183ca6;
         --border: #d9e1ef;
         --shadow: 0 24px 70px rgba(23, 38, 68, 0.14);
         --radius-lg: 28px;
         --radius-md: 18px;
       }

       * {
         box-sizing: border-box;
       }

       html {
         min-width: 320px;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         line-height: 1.6;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(40, 84, 216, 0.16), transparent 34rem),
           linear-gradient(135deg, #fbfcff 0%, var(--bg) 55%, #eef3fb 100%);
       }

       .skip-link {
         position: absolute;
         top: 1rem;
         left: 1rem;
         z-index: 10;
         transform: translateY(-150%);
         padding: 0.75rem 1rem;
         color: #ffffff;
         background: var(--accent-strong);
         border-radius: 999px;
         font-weight: 700;
         text-decoration: none;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid #111827;
         outline-offset: 3px;
       }

       .page {
         width: min(1120px, 100%);
         margin: 0 auto;
         padding: 4rem 1rem;
       }

       .hero {
         display: grid;
         grid-template-columns: minmax(0, 1.2fr) minmax(240px, 0.8fr);
         gap: 2rem;
         align-items: center;
         margin-bottom: 2rem;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         margin: 0 0 1rem;
         padding: 0.35rem 0.8rem;
         color: var(--accent-strong);
         background: rgba(40, 84, 216, 0.1);
         border: 1px solid rgba(40, 84, 216, 0.2);
         border-radius: 999px;
         font-size: 0.9rem;
         font-weight: 700;
       }

       h1 {
         max-width: 12ch;
         margin: 0;
         font-size: clamp(2.6rem, 8vw, 5.75rem);
         line-height: 0.95;
         letter-spacing: -0.07em;
       }

       .intro {
         max-width: 38rem;
         margin: 1.25rem 0 0;
         color: var(--muted);
         font-size: clamp(1rem, 2vw, 1.2rem);
       }

       .hero-card {
         padding: 1.25rem;
         background: rgba(255, 255, 255, 0.78);
         border: 1px solid rgba(217, 225, 239, 0.9);
         border-radius: var(--radius-lg);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .hero-card p {
         margin: 0;
         color: var(--muted);
       }

       .hero-card strong {
         display: block;
         margin-bottom: 0.35rem;
         color: var(--text);
         font-size: 1.1rem;
       }

       .faq {
         display: grid;
         gap: 1rem;
         padding: 1rem;
         background: rgba(255, 255, 255, 0.62);
         border: 1px solid rgba(217, 225, 239, 0.78);
         border-radius: var(--radius-lg);
         box-shadow: var(--shadow);
       }

       .example {
         overflow: hidden;
         background: var(--surface);
         border: 1px solid var(--border);
         border-radius: var(--radius-md);
         transition:
           border-color 180ms ease,
           box-shadow 180ms ease,
           transform 180ms ease;
       }

       .example:focus-within,
       .example:hover {
         border-color: rgba(40, 84, 216, 0.45);
         box-shadow: 0 14px 36px rgba(23, 38, 68, 0.1);
         transform: translateY(-1px);
       }

       h2 {
         margin: 0;
         font-size: 1rem;
       }

       .question {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         width: 100%;
         min-height: 64px;
         padding: 1.15rem 1.25rem;
         color: var(--text);
         background: transparent;
         border: 0;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         text-align: left;
       }

       .question:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: -6px;
         border-radius: calc(var(--radius-md) - 2px);
       }

       .question::after {
         flex: 0 0 auto;
         width: 2rem;
         height: 2rem;
         color: var(--accent);
         background:
           linear-gradient(currentColor, currentColor) center / 0.85rem 0.14rem no-repeat,
           linear-gradient(currentColor, currentColor) center / 0.14rem 0.85rem no-repeat,
           var(--surface-strong);
         border: 1px solid rgba(40, 84, 216, 0.22);
         border-radius: 50%;
         content: "";
         transition: transform 180ms ease;
       }

       .question[aria-expanded="true"]::after {
         transform: rotate(45deg);
       }

       .details {
         padding: 0 1.25rem 1.25rem;
         color: var(--muted);
       }

       .details p {
         max-width: 70ch;
         margin: 0;
       }

       .details[hidden] {
         display: none;
       }

       @media (prefers-reduced-motion: reduce) {
