           padding: 0 1rem 1rem;
         }
       }

       @media (forced-colors: active) {
         .skip-link,
         .eyebrow,
         .hero-card,
         .faq,
         .example,
         .question::after {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .question:focus-visible {
           outline: 3px solid Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main" class="page">
       <section class="hero" aria-labelledby="page-title">
         <div>
           <p class="eyebrow">Cat care essentials</p>
           <h1 id="page-title">FAQ about cats</h1>
           <p class="intro">
             Quick, practical answers for curious cat people, from purring and play
             to feeding routines and healthy habits.
           </p>
         </div>
         <div class="hero-card">
           <strong>Tip of the day</strong>
           <p>
             Cats thrive on predictable routines, gentle handling, and daily
             play that lets them stalk, chase, and pounce.
           </p>
         </div>
       </section>

       <section class="faq" aria-label="Frequently asked questions about cats">
         <div class="example">
           <h2>
             <button
               class="question"
               type="button"
               aria-expanded="true"
               aria-controls="answer-purr"
             >
               Why do cats purr?
             </button>
           </h2>
           <div class="details" id="answer-purr">
             <p>
               Cats often purr when they feel content, but purring can also be a
               way to self-soothe when they are stressed, tired, or recovering.
             </p>
           </div>
         </div>

         <div class="example">
           <h2>
             <button
               class="question"
               type="button"
               aria-expanded="true"
               aria-controls="answer-knead"
             >
               Why does my cat knead blankets?
             </button>
           </h2>
           <div class="details" id="answer-knead">
             <p>
               Kneading is a comforting behavior that begins in kittenhood. Adult
               cats may knead soft surfaces when they feel relaxed, affectionate,
               or ready to settle down.
             </p>
           </div>
         </div>

         <div class="example">
           <h2>
             <button
               class="question"
               type="button"
               aria-expanded="true"
               aria-controls="answer-water"
             >
               How can I encourage my cat to drink more water?
             </button>
           </h2>
           <div class="details" id="answer-water">
             <p>
               Place fresh water in quiet spots away from the litter box, try a
               wide bowl or fountain, and consider wet food if your veterinarian
               says it fits your cat's needs.
             </p>
           </div>
         </div>

         <div class="example">
           <h2>
             <button
               class="question"
               type="button"
               aria-expanded="true"
               aria-controls="answer-sleep"
             >
               Is it normal for cats to sleep so much?
             </button>
           </h2>
           <div class="details" id="answer-sleep">
             <p>
               Yes. Many cats sleep 12 to 16 hours a day, and kittens or senior
               cats may sleep even more. Sudden changes in sleep, appetite, or
               behavior are worth discussing with a veterinarian.
             </p>
           </div>
         </div>

         <div class="example">
           <h2>
             <button
               class="question"
               type="button"
               aria-expanded="true"
               aria-controls="answer-play"
             >
               How often should I play with my cat?
             </button>
           </h2>
           <div class="details" id="answer-play">
             <p>
               Most cats benefit from short daily play sessions. Wand toys,
               puzzle feeders, and chase games can help satisfy hunting instincts
               and reduce boredom.
             </p>
           </div>
         </div>
       </section>
     </main>

     <script>
       document.querySelectorAll(".example").forEach((item) => {
         const button = item.querySelector(".question");
         const details = item.querySelector(".details");

         button.setAttribute("aria-expanded", "false");
         details.hidden = true;

         button.addEventListener("click", () => {
           const isExpanded = button.getAttribute("aria-expanded") === "true";
           button.setAttribute("aria-expanded", String(!isExpanded));
           details.hidden = isExpanded;
         });

         button.addEventListener("keydown", (event) => {
           if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
             button.setAttribute("aria-expanded", "false");
             details.hidden = true;
           }
         });
       });
     </script>
   </body>
 </html>

